function lumAt(data,w,h,x,y){ var p=(y*w+x)*4; return 0.299*data[p]+0.587*data[p+1]+0.114*data[p+2]; }
function pixelSortProcess(data,w,h,opts){
  opts=opts||{};
  var thr=opts.thr!=null?opts.thr:40;
  var mode=opts.mode!=null?opts.mode:0;     // 0 horizontal, 1 vertical
  var maxLen=opts.maxLen!=null?opts.maxLen:60;
  if(thr<0)thr=0; else if(thr>300)thr=300;
  if(maxLen<4)maxLen=4; else if(maxLen>200)maxLen=200;
  var out=new Uint8ClampedArray(data);
  function lumaOf(idx){ var p=idx*4; return 0.299*data[p]+0.587*data[p+1]+0.114*data[p+2]; }
  if(mode===1){
    for(var x=0;x<w;x++){
      var run=[];
      for(var y=0;y<=h;y++){
        var inRun = (y<h) && (lumAt(data,w,h,x,y)>=thr);
        if(inRun){ run.push(y); }
        else { if(run.length>1 && run.length<=maxLen){ sortRun(out,w,h,x,run,true); } run=[]; }
      }
    }
  } else {
    for(var y=0;y<h;y++){
      var run2=[];
      for(var x2=0;x2<=w;x2++){
        var inRun2 = (x2<w) && (lumAt(data,w,h,x2,y)>=thr);
        if(inRun2){ run2.push(x2); }
        else { if(run2.length>1 && run2.length<=maxLen){ sortRun(out,w,h,y,run2,false); } run2=[]; }
      }
    }
  }
  return out;
}
function sortRun(out,w,h,fix,run,isVert){
  // fix = constant coordinate, run = varying coordinate. pixel index = fix*w + run[i] (both modes)
  var cols=[];
  for(var i=0;i<run.length;i++){ var idx=fix*w+run[i]; var p=idx*4; cols.push([out[p],out[p+1],out[p+2],out[p+3]]); }
  cols.sort(function(a,b){var la=0.299*a[0]+0.587*a[1]+0.114*a[2];var lb=0.299*b[0]+0.587*b[1]+0.114*b[2];return la-lb;});
  for(var i3=0;i3<run.length;i3++){ var idx3=fix*w+run[i3]; var p3=idx3*4; out[p3]=cols[i3][0]; out[p3+1]=cols[i3][1]; out[p3+2]=cols[i3][2]; out[p3+3]=cols[i3][3]; }
}

var EXPORTS={pixelSortProcess:pixelSortProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PixelSortForgePure = EXPORTS; }
